const std = @import("std");
const builtin = @import("builtin");

pub const HEAP_MAGIC: [8]u8 = .{ 'Z', 'I', 'G', 'P', 'H', 'E', 'A', 'P' };
pub const HEAP_VERSION: u32 = 1;
pub const HEADER_SIZE: u64 = @as(u64, @sizeOf(HeapHeader));

pub const Endianness = enum(u32) {
    little = 0x01234567,
    big = 0x76543210,
};

pub const RootPointer = struct {
    offset: u64,
    uuid: u128,
};

fn nativeEndianness() Endianness {
    return if (builtin.target.cpu.arch.endian() == .little) .little else .big;
}

fn crc32c(bytes: []const u8, skip_start: usize, skip_len: usize) u32 {
    var crc: u32 = 0xFFFFFFFF;
    for (bytes, 0..) |byte, i| {
        if (i >= skip_start and i < skip_start + skip_len) continue;
        crc = crc32cByte(crc, byte);
    }
    return crc ^ 0xFFFFFFFF;
}

fn crc32cByte(crc: u32, byte: u8) u32 {
    const poly: u32 = 0x82F63B78;
    var c = crc ^ @as(u32, byte);
    var j: usize = 0;
    while (j < 8) : (j += 1) {
        c = if ((c & 1) != 0) (c >> 1) ^ poly else c >> 1;
    }
    return c;
}

fn isAligned(offset: u64, alignment: u64) bool {
    return alignment != 0 and offset % alignment == 0;
}

pub const HeapHeader = extern struct {
    magic: [8]u8,
    version: u32,
    flags: u32,
    pool_uuid_low: u64,
    pool_uuid_high: u64,
    endianness: Endianness,
    checksum: u32,
    reserved1: u32,
    heap_size: u64,
    used_size: u64,
    root_offset: u64,
    root_uuid_low: u64,
    root_uuid_high: u64,
    allocator_offset: u64,
    transaction_id: u64,
    last_checkpoint: u64,
    reserved2: [256 - 112]u8,

    pub const FLAG_DIRTY: u32 = 0x01;

    pub fn init(heap_size: u64) !HeapHeader {
        if (heap_size < @sizeOf(HeapHeader)) {
            return error.HeapTooSmall;
        }

        var header = HeapHeader{
            .magic = HEAP_MAGIC,
            .version = HEAP_VERSION,
            .flags = 0,
            .pool_uuid_low = std.crypto.random.int(u64),
            .pool_uuid_high = std.crypto.random.int(u64),
            .endianness = nativeEndianness(),
            .checksum = 0,
            .reserved1 = 0,
            .heap_size = heap_size,
            .used_size = @sizeOf(HeapHeader),
            .root_offset = 0,
            .root_uuid_low = 0,
            .root_uuid_high = 0,
            .allocator_offset = 0,
            .transaction_id = 0,
            .last_checkpoint = 0,
            .reserved2 = [_]u8{0} ** (256 - 112),
        };

        header.updateChecksum();
        return header;
    }

    pub fn computeChecksum(self: *const HeapHeader) u32 {
        const bytes = std.mem.asBytes(self);
        return crc32c(bytes, @offsetOf(HeapHeader, "checksum"), @sizeOf(u32));
    }

    pub fn validate(self: *const HeapHeader) !void {
        if (!std.mem.eql(u8, self.magic[0..], HEAP_MAGIC[0..])) {
            return error.InvalidMagic;
        }

        if (self.version != HEAP_VERSION) {
            return error.UnsupportedVersion;
        }

        if (self.endianness != nativeEndianness()) {
            return error.EndiannessMismatch;
        }

        if (self.heap_size < @sizeOf(HeapHeader)) {
            return error.InvalidHeapSize;
        }

        if (self.used_size < @sizeOf(HeapHeader) or self.used_size > self.heap_size) {
            return error.InvalidUsedSize;
        }

        if (self.root_offset == 0) {
            if (self.root_uuid_low != 0 or self.root_uuid_high != 0) {
                return error.InvalidRootPointer;
            }
        } else {
            if (self.root_offset < @sizeOf(HeapHeader) or self.root_offset >= self.heap_size) {
                return error.InvalidRootPointer;
            }
            if (!isAligned(self.root_offset, @alignOf(ObjectHeader))) {
                return error.InvalidRootPointerAlignment;
            }
            if (self.root_uuid_low == 0 and self.root_uuid_high == 0) {
                return error.InvalidRootPointer;
            }
        }

        if (self.allocator_offset != 0) {
            if (self.allocator_offset < @sizeOf(HeapHeader) or self.allocator_offset >= self.heap_size) {
                return error.InvalidAllocatorOffset;
            }
            if (!isAligned(self.allocator_offset, @alignOf(FreeBlock))) {
                return error.InvalidAllocatorOffsetAlignment;
            }
        }

        if (self.computeChecksum() != self.checksum) {
            return error.ChecksumMismatch;
        }
    }

    pub fn getPoolUUID(self: *const HeapHeader) u128 {
        return (@as(u128, self.pool_uuid_high) << 64) | @as(u128, self.pool_uuid_low);
    }

    pub fn setPoolUUID(self: *HeapHeader, uuid: u128) void {
        self.pool_uuid_low = @as(u64, @truncate(uuid));
        self.pool_uuid_high = @as(u64, @truncate(uuid >> 64));
        self.updateChecksum();
    }

    pub fn getRootPtr(self: *const HeapHeader) ?RootPointer {
        if (self.root_offset == 0) {
            return null;
        }
        return .{
            .offset = self.root_offset,
            .uuid = (@as(u128, self.root_uuid_high) << 64) | @as(u128, self.root_uuid_low),
        };
    }

    pub fn setRootPtr(self: *HeapHeader, offset: u64, uuid: u128) !void {
        if (offset < @sizeOf(HeapHeader)) {
            return error.InvalidRootPointer;
        }
        if (!isAligned(offset, @alignOf(ObjectHeader))) {
            return error.InvalidRootPointerAlignment;
        }
        if (uuid == 0) {
            return error.InvalidRootUUID;
        }

        self.root_offset = offset;
        self.root_uuid_low = @as(u64, @truncate(uuid));
        self.root_uuid_high = @as(u64, @truncate(uuid >> 64));
        self.updateChecksum();
    }

    pub fn clearRootPtr(self: *HeapHeader) void {
        self.root_offset = 0;
        self.root_uuid_low = 0;
        self.root_uuid_high = 0;
        self.updateChecksum();
    }

    pub fn updateChecksum(self: *HeapHeader) void {
        self.checksum = 0;
        self.checksum = self.computeChecksum();
    }

    pub fn isDirty(self: *const HeapHeader) bool {
        return (self.flags & FLAG_DIRTY) != 0;
    }

    pub fn setDirty(self: *HeapHeader, dirty: bool) void {
        if (dirty) {
            self.flags |= FLAG_DIRTY;
        } else {
            self.flags &= ~FLAG_DIRTY;
        }
        self.updateChecksum();
    }
};

pub const ObjectHeader = extern struct {
    magic: u32,
    flags: u32,
    size: u64,
    ref_count: u32,
    schema_id: u32,
    checksum: u32,
    reserved: u32,

    pub const OBJECT_MAGIC: u32 = 0xDEADBEEF;
    pub const FLAG_FREED: u32 = 0x01;
    pub const FLAG_PINNED: u32 = 0x02;
    pub const FLAG_ARRAY: u32 = 0x04;

    pub fn init(size: u64, schema_id: u32) !ObjectHeader {
        if (size < @sizeOf(ObjectHeader)) {
            return error.ObjectTooSmall;
        }

        var header = ObjectHeader{
            .magic = OBJECT_MAGIC,
            .flags = 0,
            .size = size,
            .ref_count = 1,
            .schema_id = schema_id,
            .checksum = 0,
            .reserved = 0,
        };

        header.updateChecksum();
        return header;
    }

    pub fn validate(self: *const ObjectHeader) !void {
        if (self.magic != OBJECT_MAGIC) {
            return error.InvalidObjectMagic;
        }

        if (self.size < @sizeOf(ObjectHeader)) {
            return error.InvalidObjectSize;
        }

        if (self.reserved != 0) {
            return error.InvalidObjectReserved;
        }

        if (self.isFreed()) {
            if (self.ref_count != 0) {
                return error.InvalidFreedRefCount;
            }
        } else {
            if (self.ref_count == 0) {
                return error.InvalidRefCount;
            }
        }

        if (self.computeChecksum() != self.checksum) {
            return error.ObjectChecksumMismatch;
        }
    }

    pub fn isFreed(self: *const ObjectHeader) bool {
        return (self.flags & FLAG_FREED) != 0;
    }

    pub fn isPinned(self: *const ObjectHeader) bool {
        return (self.flags & FLAG_PINNED) != 0;
    }

    pub fn isArray(self: *const ObjectHeader) bool {
        return (self.flags & FLAG_ARRAY) != 0;
    }

    pub fn setFreed(self: *ObjectHeader, freed: bool) void {
        if (freed) {
            self.flags |= FLAG_FREED;
            self.ref_count = 0;
        } else {
            self.flags &= ~FLAG_FREED;
            if (self.ref_count == 0) {
                self.ref_count = 1;
            }
        }
        self.updateChecksum();
    }

    pub fn setPinned(self: *ObjectHeader, pinned: bool) void {
        if (pinned) {
            self.flags |= FLAG_PINNED;
        } else {
            self.flags &= ~FLAG_PINNED;
        }
        self.updateChecksum();
    }

    pub fn setArray(self: *ObjectHeader, is_array: bool) void {
        if (is_array) {
            self.flags |= FLAG_ARRAY;
        } else {
            self.flags &= ~FLAG_ARRAY;
        }
        self.updateChecksum();
    }

    pub fn computeChecksum(self: *const ObjectHeader) u32 {
        const bytes = std.mem.asBytes(self);
        return crc32c(bytes, @offsetOf(ObjectHeader, "checksum"), @sizeOf(u32));
    }

    pub fn updateChecksum(self: *ObjectHeader) void {
        self.checksum = 0;
        self.checksum = self.computeChecksum();
    }
};

pub const FreeBlock = extern struct {
    magic: u32,
    size: u64,
    prev_offset: u64,
    next_offset: u64,
    checksum: u32,
    reserved: u32,

    pub const FREE_MAGIC: u32 = 0xFEEDFACE;

    pub fn init(size: u64) !FreeBlock {
        if (size < @sizeOf(FreeBlock)) {
            return error.FreeBlockTooSmall;
        }

        var block = FreeBlock{
            .magic = FREE_MAGIC,
            .size = size,
            .prev_offset = 0,
            .next_offset = 0,
            .checksum = 0,
            .reserved = 0,
        };

        block.updateChecksum();
        return block;
    }

    pub fn validate(self: *const FreeBlock) !void {
        if (self.magic != FREE_MAGIC) {
            return error.InvalidFreeBlockMagic;
        }

        if (self.size < @sizeOf(FreeBlock)) {
            return error.InvalidFreeBlockSize;
        }

        if (self.reserved != 0) {
            return error.InvalidFreeBlockReserved;
        }

        if (self.prev_offset != 0 and !isAligned(self.prev_offset, @alignOf(FreeBlock))) {
            return error.InvalidFreeBlockPrevOffset;
        }

        if (self.next_offset != 0 and !isAligned(self.next_offset, @alignOf(FreeBlock))) {
            return error.InvalidFreeBlockNextOffset;
        }

        if (self.computeChecksum() != self.checksum) {
            return error.FreeBlockChecksumMismatch;
        }
    }

    pub fn computeChecksum(self: *const FreeBlock) u32 {
        const bytes = std.mem.asBytes(self);
        return crc32c(bytes, @offsetOf(FreeBlock, "checksum"), @sizeOf(u32));
    }

    pub fn updateChecksum(self: *FreeBlock) void {
        self.checksum = 0;
        self.checksum = self.computeChecksum();
    }

    pub fn setPrevOffset(self: *FreeBlock, offset: u64) !void {
        if (offset != 0 and !isAligned(offset, @alignOf(FreeBlock))) {
            return error.InvalidFreeBlockPrevOffset;
        }
        self.prev_offset = offset;
        self.updateChecksum();
    }

    pub fn setNextOffset(self: *FreeBlock, offset: u64) !void {
        if (offset != 0 and !isAligned(offset, @alignOf(FreeBlock))) {
            return error.InvalidFreeBlockNextOffset;
        }
        self.next_offset = offset;
        self.updateChecksum();
    }
};

